1	import React, { useState, useEffect } from 'react';
2	import './Header.css';
3	
4	/**
5	 * Header — app-level header bar.
6	 *
7	 * Shows the PC Pal title, user info (clickable to edit), and buddy button.
8	 */
9	function Header({ user, onBuddyClick, buddyBadge, onUpdateProfile, onDashboardClick, showingDashboard, onSignOut, onAdminClick, showingAdmin }) {
10	  const [editing, setEditing] = useState(false);
11	  const [editName, setEditName] = useState('');
12	  const [editOs, setEditOs] = useState('');
13	  const [editComfort, setEditComfort] = useState(1);
14	  const [editModel, setEditModel] = useState('');
15	  const [editTrainingOptIn, setEditTrainingOptIn] = useState(false);
16	  const [availableModels, setAvailableModels] = useState([]);
17	  const [saving, setSaving] = useState(false);
18	  const [saveError, setSaveError] = useState('');
19	  const [showMemories, setShowMemories] = useState(false);
20	  const [memories, setMemories] = useState([]);
21	  const [loadingMemories, setLoadingMemories] = useState(false);
22	
23	  // Fetch available models when edit modal opens
24	  useEffect(() => {
25	    if (!editing) return;
26	    fetch('/api/models')
27	      .then(r => r.json())
28	      .then(data => setAvailableModels(data))
29	      .catch(() => setAvailableModels([]));
30	  }, [editing]);
31	
32	  const openEdit = () => {
33	    if (!user) return;
34	    setEditName(user.name || '');
35	    setEditOs(user.os_type || 'Windows');
36	    setEditComfort(user.comfort_level || 1);
37	    setEditModel(user.model_preference || '');
38	    setEditTrainingOptIn(Boolean(user.training_opt_in));
39	    setSaveError('');
40	    setEditing(true);
41	  };
42	
43	  const handleSave = async () => {
44	    if (!onUpdateProfile) {
45	      setSaveError('Profile update is unavailable right now.');
46	      return;
47	    }
48	    if (!editName.trim()) {
49	      setSaveError('Please enter your name.');
50	      return;
51	    }
52	    setSaveError('');
53	    setSaving(true);
54	    try {
55	      const result = await onUpdateProfile({
56	        name: editName.trim(),
57	        os_type: editOs,
58	        comfort_level: editComfort,
59	        model_preference: editModel || null,
60	        training_opt_in: editTrainingOptIn ? 1 : 0,
61	      });
62	      if (!result) {
63	        throw new Error('No profile was returned. Try reloading the page.');
64	      }
65	      setEditing(false);
66	    } catch (e) {
67	      console.error('Failed to update profile:', e);
68	      setSaveError(e?.message || 'Could not save your profile. Please try again.');
69	    } finally {
70	      setSaving(false);
71	    }
72	  };
73	
74	  return (
75	    <header className="app-header">
76	      <div className="app-header__brand">
77	        <span className="app-header__logo" aria-hidden="true">PC</span>
78	        <div>
79	          <h1 className="app-header__title">PC Pal</h1>
80	          <p className="app-header__subtitle">Your Friendly Tech Helper</p>
81	        </div>
82	      </div>
83	
84	      <div className="app-header__right">
85	        {onDashboardClick && (
86	          <button
87	            className={`app-header__dash-btn ${showingDashboard ? 'app-header__dash-btn--active' : ''}`}
88	            onClick={onDashboardClick}
89	          >
90	            Dashboard
91	          </button>
92	        )}
93	        {onAdminClick && user && user.is_admin ? (
94	          <button
95	            className={`app-header__dash-btn ${showingAdmin ? 'app-header__dash-btn--active' : ''}`}
96	            onClick={onAdminClick}
97	          >
98	            Admin
99	          </button>
100	        ) : null}
101	        {onBuddyClick && (
102	          <button
103	            className="app-header__buddy-btn"
104	            onClick={onBuddyClick}
105	            aria-label={buddyBadge > 0 ? `Buddy (${buddyBadge} updates)` : 'Buddy'}
106	          >
107	            Buddy
108	            {buddyBadge > 0 && (
109	              <span className="app-header__buddy-badge" aria-hidden="true">
110	                {buddyBadge}
111	              </span>
112	            )}
113	          </button>
114	        )}
115	
116	        {user && (
117	          <button className="app-header__user" onClick={openEdit} title="Click to edit your profile">
118	            <span className="app-header__user-greeting">
119	              Hi, <strong>{user.name || (user.is_anonymous ? 'guest' : 'friend')}</strong>!
120	            </span>
121	            {user.os_type && (
122	              <span className="app-header__user-os">{user.os_type}</span>
123	            )}
124	          </button>
125	        )}
126	        {onSignOut && user && !user.is_anonymous && (
127	          <button
128	            type="button"
129	            className="app-header__signout"
130	            onClick={onSignOut}
131	            aria-label="Sign out"
132	          >
133	            Sign out
134	          </button>
135	        )}
136	      </div>
137	
138	      {editing && (
139	        <div className="profile-edit-overlay" onClick={() => setEditing(false)}>
140	          <div className="profile-edit" onClick={e => e.stopPropagation()}>
141	            <h2 className="profile-edit__title">Edit Your Profile</h2>
142	
143	            <label className="profile-edit__label">
144	              Your name
145	              <input
146	                type="text"
147	                className="profile-edit__input"
148	                value={editName}
149	                onChange={e => setEditName(e.target.value)}
150	                autoFocus
151	              />
152	            </label>
153	
154	            <label className="profile-edit__label">
155	              Your device
156	              <select className="profile-edit__select" value={editOs} onChange={e => setEditOs(e.target.value)}>
157	                <option value="Windows">Windows PC</option>
158	                <option value="Mac">Mac</option>
159	                <option value="iPhone">iPhone</option>
160	                <option value="Android">Android</option>
161	              </select>
162	            </label>
163	
164	            <label className="profile-edit__label">
165	              Comfort level
166	              <select className="profile-edit__select" value={editComfort} onChange={e => setEditComfort(Number(e.target.value))}>
