1	import { useState, useEffect, useLayoutEffect, useRef, useCallback } from 'react';
2	import { collectBrowserSystemInfo } from '../utils/collectBrowserSystemInfo';
3	
4	/**
5	 * useChat — WebSocket chat hook for PC Pal
6	 *
7	 * Connects to /ws (proxied to ws://localhost:3001/ws by Vite),
8	 * sends an init message, and manages message state.
9	 *
10	 * @param {string|null} userId
11	 * @returns {object} chat state + callbacks (see destructured return below)
12	 */
13	export function useChat(userId) {
14	  const [messages, setMessages] = useState([]);
15	  const [isConnected, setIsConnected] = useState(false);
16	  const [isTyping, setIsTyping] = useState(false);
17	  const [connectionFailed, setConnectionFailed] = useState(false);
18	  const [activeSequence, setActiveSequence] = useState(null);
19	  const [welcomeBack, setWelcomeBack] = useState(null);
20	  const [conversationId, setConversationId] = useState(null);
21	  const [feedbackPrompt, setFeedbackPrompt] = useState(null);
22	  const [agentConnected, setAgentConnected] = useState(false);
23	  // Standalone terminal history (user's own terminal panel)
24	  const [terminalHistory, setTerminalHistory] = useState([]);
25	  const [terminalCwd, setTerminalCwd] = useState(null);
26	  // Buddy session state — set when THIS user is observing a learner's session
27	  const [buddySession, setBuddySession] = useState(null);
28	  // Set when a buddy is observing OUR session (we are the learner)
29	  const [buddyObserving, setBuddyObserving] = useState(null);
30	
31	  const wsRef = useRef(null);
32	  const reconnectTimeoutRef = useRef(null);
33	  const messageIdRef = useRef(0);
34	  const reconnectAttemptsRef = useRef(0);
35	  const connectRef = useRef(null);
36	  const conversationIdRef = useRef(null);
37	
38	  const nextId = () => {
39	    messageIdRef.current += 1;
40	    return messageIdRef.current;
41	  };
42	
43	  // Keep a ref in sync so callbacks can read the latest conversation id
44	  // without being re-created on every change.
45	  useEffect(() => {
46	    conversationIdRef.current = conversationId;
47	  }, [conversationId]);
48	
49	  const connect = useCallback(() => {
50	    if (!userId) return;
51	
52	    // Determine WS URL: use relative path so Vite proxy handles it
53	    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
54	    const wsUrl = `${protocol}//${window.location.host}/ws`;
55	
56	    const ws = new WebSocket(wsUrl);
57	    wsRef.current = ws;
58	
59	    ws.onopen = () => {
60	      setIsConnected(true);
61	      setConnectionFailed(false);
62	      reconnectAttemptsRef.current = 0;
63	      // Send init message so the server knows who we are
64	      const browserSystemInfo = collectBrowserSystemInfo();
65	      ws.send(JSON.stringify({ type: 'init', userId, browserSystemInfo }));
66	    };
67	
68	    ws.onmessage = (event) => {
69	      let data;
70	      try {
71	        data = JSON.parse(event.data);
72	      } catch {
73	        console.error('PC Pal: invalid JSON from server', event.data);
74	        return;
75	      }
76	
77	      switch (data.type) {
78	        case 'init_ack':
79	          if (data.conversationId) {
80	            setConversationId(data.conversationId);
81	          }
82	          break;
83	
84	        case 'welcome_back':
85	          setWelcomeBack({
86	            reviewSkills: data.reviewSkills || [],
87	            pendingHelp: data.pendingHelp || [],
88	          });
89	          break;
90	
91	        case 'typing':
92	          setIsTyping(true);
93	          break;
94	
95	        case 'response':
96	          setIsTyping(false);
97	          setMessages((prev) => [
98	            ...prev,
99	            {
100	              id: nextId(),
101	              role: 'assistant',
102	              text: data.text ?? '',
103	              timestamp: new Date().toISOString(),
104	              safetyAlert: data.safetyAlert ?? null,
105	              stepSequence: data.stepSequence || null,
106	              images: data.images || null,
107	              videos: data.videos || null,
108	              guide: data.guide || null,
109	              findings: data.findings || null,
110	              practice: data.practice || null,
111	              screenshot: data.screenshot || null,
112	            },
113	          ]);
114	          if (data.stepSequence) {
115	            if (data.stepSequence.completed) {
116	              setActiveSequence(null);
117	            } else {
118	              setActiveSequence(data.stepSequence);
119	            }
120	          }
121	          if (data.conversationId) {
122	            setConversationId(data.conversationId);
123	          }
124	          if (data.endedConversationId) {
125	            setFeedbackPrompt({ conversationId: data.endedConversationId });
126	          }
127	          break;
128	
129	        case 'resources':
130	          setIsTyping(false);
131	          setMessages((prev) => [
132	            ...prev,
133	            {
134	              id: nextId(),
135	              role: 'assistant',
136	              text: data.text ?? '',
137	              timestamp: new Date().toISOString(),
138	              resources: data.resources || null,
139	            },
140	          ]);
141	          break;
142	
143	        case 'command_result':
144	          // Update the command result in the most recent message's guide
145	          setMessages((prev) => {
146	            const updated = [...prev];
147	            // Find the latest assistant message with a guide
148	            for (let i = updated.length - 1; i >= 0; i--) {
149	              if (updated[i].guide) {
150	                updated[i] = {
151	                  ...updated[i],
152	                  commandResults: {
153	                    ...(updated[i].commandResults || {}),
154	                    [data.command]: { output: data.output, running: false, error: data.error },
155	                  },
156	                };
157	                break;
158	              }
159	            }
160	            return updated;
161	          });
162	          break;
163	
164	        case 'pair_result':
165	          if (data.success) {
166	            setAgentConnected(true);
167	          }
168	          // The callback is handled via pairAgent below
169	          break;
170	
171	        case 'agent_status':
172	          setAgentConnected(!!data.connected);
173	          break;
174	
175	        case 'new_chat_ack':
176	          // Server created a fresh session after closing the previous one
177	          setMessages([]);
178	          setActiveSequence(null);
179	          setFeedbackPrompt(null);
180	          if (data.conversationId) {
181	            setConversationId(data.conversationId);
182	          }
183	          break;
184	
185	        case 'chat_ended':
186	          // User clicked "End chat". Server confirmed the session is closed;
187	          // show the feedback modal.
188	          if (data.conversationId) {
189	            setFeedbackPrompt({ conversationId: data.conversationId });
190	          }
191	          break;
192	
193	        case 'error':
194	          setIsTyping(false);
195	          setMessages((prev) => [
196	            ...prev,
197	            {
198	              id: nextId(),
199	              role: 'assistant',
200	              text: data.message ?? 'Something went wrong. Please try again.',
201	              timestamp: new Date().toISOString(),
202	              safetyAlert: null,
203	            },
204	          ]);
205	          break;
206	
207	        case 'terminal_result':
208	          setTerminalHistory(prev => prev.map(entry =>
209	            entry.requestId === data.requestId
210	              ? { ...entry, output: data.output, error: data.error, running: false }
211	              : entry
212	          ));
213	          if (data.cwd) setTerminalCwd(data.cwd);
214	          break;
215	
216	        // ─── Buddy session messages ───
217	        case 'buddy_join_ack':
218	          setBuddySession({
219	            learnerId: data.learnerId,
220	            learnerName: data.learnerName,
221	            messages: (data.messages || []).map((m, i) => ({ ...m, id: 'bh_' + i })),
222	            terminalHistory: [],
223	          });
224	          break;
225	
226	        case 'buddy_chat_forward':
227	          setBuddySession(prev => prev ? {
228	            ...prev,
229	            messages: [...prev.messages, { id: 'bf_' + Date.now(), role: data.role, text: data.text, timestamp: data.timestamp }],
230	          } : prev);
231	          break;
232	
233	        case 'buddy_command_result':
234	          setBuddySession(prev => {
235	            if (!prev) return prev;
236	            return {
237	              ...prev,
238	              cwd: data.cwd || prev.cwd,
239	              terminalHistory: prev.terminalHistory.map(entry =>
240	                entry.requestId === data.requestId
241	                  ? { ...entry, output: data.output, error: data.error, running: false }
242	                  : entry
243	              ),
244	            };
245	          });
246	          break;
247	
248	        case 'buddy_joined':
249	          setBuddyObserving({ buddyName: data.buddyName });
250	          break;
251	
252	        case 'buddy_left':
253	          setBuddyObserving(null);
254	          break;
255	
256	        case 'buddy_terminal_start':
257	          // Learner sees buddy starting a command
258	          setMessages(prev => [...prev, {
259	            id: 'bt_' + data.requestId,
260	            role: 'assistant',
261	            text: `${data.buddyName} is running a diagnostic command...`,
262	            timestamp: new Date().toISOString(),
263	            buddyTerminal: { requestId: data.requestId, command: data.command, output: '', error: false, running: true, buddyName: data.buddyName },
264	          }]);
265	          break;
266	
267	        case 'buddy_terminal_result':
268	          // Update the pending terminal message with the result
269	          setMessages(prev => prev.map(m =>
270	            m.buddyTerminal && m.buddyTerminal.requestId === data.requestId
271	              ? { ...m, text: `${data.buddyName} ran: ${data.command}`, buddyTerminal: { ...m.buddyTerminal, output: data.output, error: data.error, running: false } }
272	              : m
273	          ));
274	          break;
275	
276	        default:
277	          console.warn('PC Pal: unknown message type', data.type);
278	      }
279	    };
280	
281	    ws.onclose = () => {
282	      setIsConnected(false);
283	      setIsTyping(false);
284	      const attempts = reconnectAttemptsRef.current;
285	      if (attempts >= 5) {
286	        setConnectionFailed(true);
287	        return;
288	      }
289	      reconnectAttemptsRef.current = attempts + 1;
290	      const delay = Math.min(1000 * Math.pow(2, attempts), 30000);
291	      reconnectTimeoutRef.current = setTimeout(() => connectRef.current?.(), delay);
292	    };
293	
294	    ws.onerror = (err) => {
295	      console.error('PC Pal WebSocket error', err);
296	      ws.close();
297	    };
298	  }, [userId]);
299	
300	  // Keep the ref in sync so ws.onclose can call the latest connect without
301	  // capturing it as a const (which would be a temporal dead zone violation).
302	  useLayoutEffect(() => {
303	    connectRef.current = connect;
304	  });
305	
306	  useEffect(() => {
307	    if (!userId) return;
308	    connect();
309	
310	    return () => {
311	      clearTimeout(reconnectTimeoutRef.current);
312	      if (wsRef.current) {
313	        // Remove the onclose handler before closing so we don't trigger reconnect
314	        wsRef.current.onclose = null;
315	        wsRef.current.close();
316	      }
317	    };
318	  }, [userId, connect]);
319	
320	  /**
321	   * Send a chat message.
322	   * @param {string} text
323	   */
324	  const sendMessage = useCallback(
325	    (text) => {
326	      const trimmed = text.trim();
327	      if (!trimmed) return;
328	
329	      // Optimistically add the user's message to the list
330	      setMessages((prev) => [
331	        ...prev,
332	        {
333	          id: nextId(),
334	          role: 'user',
335	          text: trimmed,
336	          timestamp: new Date().toISOString(),
337	          safetyAlert: null,
338	        },
339	      ]);
340	
341	      if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
342	        wsRef.current.send(JSON.stringify({ type: 'chat', text: trimmed }));
343	      } else {
344	        console.warn('PC Pal: WebSocket not open, message not sent');
345	        setMessages((prev) => [
346	          ...prev,
347	          {
348	            id: nextId(),
349	            role: 'assistant',
350	            text: 'Sorry, the connection was lost. Please refresh the page and try again.',
351	            timestamp: new Date().toISOString(),
352	            safetyAlert: null,
353	          },
354	        ]);
355	      }
356	    },
357	    [],
358	  );
359	
360	  const dismissWelcomeBack = useCallback(() => setWelcomeBack(null), []);
361	
362	  /**
363	   * Pair with a relay agent using a code. Calls back with { success, message }.
364	   */
365	  const pairAgent = useCallback((code, callback) => {
366	    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
367	      callback({ success: false, message: 'Not connected to PC Pal server.' });
368	      return;
369	    }
370	    // Listen for the pair result
371	    const handler = (event) => {
372	      let data;
373	      try { data = JSON.parse(event.data); } catch { return; }
374	      if (data.type === 'pair_result') {
375	        wsRef.current.removeEventListener('message', handler);
376	        if (data.success) setAgentConnected(true);
377	        callback(data);
378	      }
379	    };
380	    wsRef.current.addEventListener('message', handler);
381	    wsRef.current.send(JSON.stringify({ type: 'pair_agent', code }));
382	  }, []);
383	
384	  /**
385	   * Gather resources (videos + links) related to the conversation.
386	   * Optionally takes extra text from the input field for context.
387	   */
388	  const gatherResources = useCallback((extraText) => {
389	    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) return;
390	    setIsTyping(true);
391	    // Add a user message showing what was requested
392	    const displayText = extraText
393	      ? `Find resources about: ${extraText}`
394	      : 'Find resources related to our conversation';
395	    setMessages((prev) => [
396	      ...prev,
397	      { id: nextId(), role: 'user', text: displayText, timestamp: new Date().toISOString() },
398	    ]);
399	    wsRef.current.send(JSON.stringify({
400	      type: 'gather_resources',
401	      text: extraText || '',
402	    }));
403	  }, []);
404	
405	  /**
406	   * Run a user-approved command from a guide artifact.
