390	            learnerName={buddySession.learnerName}
391	            cwd={buddySession.cwd}
392	          />
393	        </div>
394	      ) : showLocalTerminal ? (
395	        <div className="side-panel side-panel--terminal">
396	          <div className="side-panel__header">
397	            <span className="side-panel__title">Terminal</span>
398	            <button className="side-panel__close" onClick={() => setTerminalOpen(false)}>Close</button>
399	          </div>
400	          <BuddyTerminal
401	            terminalHistory={terminalHistory}
402	            onRunCommand={sendTerminalCommand}
