404	            cwd={terminalCwd}
405	          />
406	        </div>
407	      ) : (
408	        <SidePanel
409	          artifact={currentArtifact}
410	          artifacts={visibleArtifacts}
411	          activeIndex={activeArtifactIdx}
412	          onNavigate={setActiveArtifactIdx}
413	          onClose={() => handleDismiss(currentArtifact.msgId)}
414	          onMoveToInline={() => handleMoveToInline(currentArtifact.msgId)}
415	          onRunCommand={runCommand}
416	          onSendMessage={sendMessage}
417	        />
418	      )
419	    )}
420	    </div>
421	  );
422	}
423	
424	export default ChatWindow;
