import React, { useEffect, useRef, useState, useMemo } from 'react';
import { useChat } from '../../hooks/useChat';
import MessageBubble from './MessageBubble';
import MessageInput from './MessageInput';
import StepSequencePanel from './StepSequencePanel';
import WelcomeBackBanner from './WelcomeBackBanner';
import FeedbackModal from './FeedbackModal';
import ConnectComputer from './ConnectComputer';
import SidePanel from './SidePanel';
import BuddyTerminal from '../Collaboration/BuddyTerminal';
import ScreenShare from './ScreenShare';
import './ChatWindow.css';

/**
 * Extract artifacts from messages — one artifact per message (not per type).
 * A message with both findings + guide becomes one combined artifact.
 */
function collectArtifacts(messages) {
  const artifacts = [];
  for (const msg of messages) {
    if (msg.role !== 'assistant') continue;
    const hasAny = msg.guide || msg.resources || msg.findings || msg.videos || msg.practice;
    if (!hasAny) continue;

    artifacts.push({
      msgId: msg.id,
      guide: msg.guide || null,
      findings: msg.findings || null,
      resources: msg.resources || null,
      videos: msg.videos || null,
      practice: msg.practice || null,
    });
  }
  return artifacts;
}

function ChatWindow({ userId, hasBuddy, viewingConversationId, onConversationChange, startNewChatRef, buddySessionTarget, onBuddySessionChange }) {
  const {
    messages: liveMessages,
    sendMessage,
    gatherResources,
    pairAgent,
    agentConnected,
    runCommand,
    isConnected,
    isTyping,
    activeSequence,
    welcomeBack,
    dismissWelcomeBack,
    conversationId,
    feedbackPrompt,
    startNewChat,
    endChat,
    submitFeedback,
    skipFeedback,
    terminalHistory,
    terminalCwd,
    sendTerminalCommand,
    buddySession,
    buddyObserving,
    joinBuddySession,
    leaveBuddySession,
    sendBuddyCommand,
    sendScreenFrame,
  } = useChat(userId);
  const [screenSharing, setScreenSharing] = useState(false);
  const bottomRef = useRef(null);

  // Expose startNewChat to parent via ref
  useEffect(() => {
    if (startNewChatRef) startNewChatRef.current = startNewChat;
  }, [startNewChat, startNewChatRef]);

  // React to buddy session target from App
  const prevBuddyTargetRef = useRef(null);
  useEffect(() => {
    if (buddySessionTarget && buddySessionTarget !== prevBuddyTargetRef.current) {
      joinBuddySession(buddySessionTarget);
    } else if (!buddySessionTarget && prevBuddyTargetRef.current) {
      leaveBuddySession(prevBuddyTargetRef.current);
    }
    prevBuddyTargetRef.current = buddySessionTarget;
  }, [buddySessionTarget, joinBuddySession, leaveBuddySession]);

  // Report buddy session state to parent
  useEffect(() => {
    if (onBuddySessionChange) onBuddySessionChange(!!buddySession);
  }, [buddySession, onBuddySessionChange]);

  // Viewing a past conversation: fetch its messages
  const [pastMessages, setPastMessages] = useState([]);
  const [loadingPast, setLoadingPast] = useState(false);
  const isViewingPast = !!(viewingConversationId && viewingConversationId !== conversationId);

  useEffect(() => {
    if (!isViewingPast || !viewingConversationId) {
      // Clear past messages when not viewing — defer to avoid setState-in-effect lint
      queueMicrotask(() => setPastMessages([]));
      return;
    }
    queueMicrotask(() => setLoadingPast(true));
    fetch(`/api/conversations/${viewingConversationId}/messages`)
      .then(r => r.json())
      .then(data => {
        const formatted = data.map((m, i) => ({
          id: i + 1,
          role: m.role,
          text: m.body,
          timestamp: m.created_at,
        }));
        setPastMessages(formatted);
      })
      .catch(() => setPastMessages([]))
      .finally(() => setLoadingPast(false));
  }, [viewingConversationId, isViewingPast]);

  // Notify parent when the live conversation changes (for sidebar refresh)
  const prevConvIdRef = useRef(conversationId);
  useEffect(() => {
    if (conversationId && conversationId !== prevConvIdRef.current) {
      prevConvIdRef.current = conversationId;
      if (onConversationChange) onConversationChange();
    }
  }, [conversationId, onConversationChange]);

  const messages = isViewingPast ? pastMessages : liveMessages;

  // Collect all artifacts from messages
  const artifacts = useMemo(() => collectArtifacts(messages), [messages]);

  // Track which message IDs have been set to inline mode
  const [inlineMsgIds, setInlineMsgIds] = useState(new Set());
  // Track which message IDs have been dismissed (closed) from the side panel
  const [dismissedMsgIds, setDismissedMsgIds] = useState(new Set());
  // User-selected artifact index (-1 = auto/latest, or explicit index)
  const [userSelectedIdx, setUserSelectedIdx] = useState(-1);
  // Standalone terminal panel open/close
  const [terminalOpen, setTerminalOpen] = useState(false);

  // Visible artifacts = all artifacts minus dismissed ones
  const visibleArtifacts = useMemo(
    () => artifacts.filter(a => !dismissedMsgIds.has(a.msgId)),
    [artifacts, dismissedMsgIds]
  );

  // Derive active artifact: show user's selection, or default to latest non-inline visible artifact
  const activeArtifactIdx = useMemo(() => {
    if (userSelectedIdx >= 0 && userSelectedIdx < visibleArtifacts.length) return userSelectedIdx;
    // Default: last visible artifact that isn't inline
    for (let i = visibleArtifacts.length - 1; i >= 0; i--) {
      if (!inlineMsgIds.has(visibleArtifacts[i].msgId)) return i;
    }
    return -1;
  }, [visibleArtifacts, inlineMsgIds, userSelectedIdx]);

  const setActiveArtifactIdx = setUserSelectedIdx;

  // Auto-scroll to the newest message
  useEffect(() => {
    if (bottomRef.current) {
      bottomRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isTyping]);

  // Dismiss welcome back when user sends their first message
  useEffect(() => {
    if (messages.length > 0 && welcomeBack) {
      const hasUserMsg = messages.some(m => m.role === 'user');
      if (hasUserMsg) dismissWelcomeBack();
    }
  }, [messages, welcomeBack, dismissWelcomeBack]);

  const hasUserMessage = messages.some(m => m.role === 'user');
  const currentArtifact = activeArtifactIdx >= 0 && activeArtifactIdx < visibleArtifacts.length
    ? visibleArtifacts[activeArtifactIdx] : null;
  const showBuddyTerminal = !!buddySession;
  // Standalone terminal is only useful when the user's own computer is paired
  // — otherwise there is nothing for commands to target. The server rejects
  // unpaired terminal commands; we hide the panel here to match.
  const showLocalTerminal = terminalOpen && agentConnected && !showBuddyTerminal;
  const showArtifactPanel = currentArtifact && !inlineMsgIds.has(currentArtifact.msgId);
  const showSidePanel = showBuddyTerminal || showLocalTerminal || showArtifactPanel;
  const showTerminal = showBuddyTerminal || showLocalTerminal;

  // Move artifact to inline mode
  const handleMoveToInline = (msgId) => {
    setInlineMsgIds(prev => new Set([...prev, msgId]));
    // If this was the active artifact, close the panel
    if (currentArtifact && currentArtifact.msgId === msgId) {
      setActiveArtifactIdx(-1);
    }
  };

  // Dismiss artifact from the side panel slider
  const handleDismiss = (msgId) => {
    setDismissedMsgIds(prev => new Set([...prev, msgId]));
    setActiveArtifactIdx(-1);
  };

  // Navigate to a specific artifact by message ID (when clicking tag in chat)
  const navigateToArtifact = (msgId) => {
    // Un-dismiss if it was dismissed
    setDismissedMsgIds(prev => {
      const next = new Set(prev);
      next.delete(msgId);
      return next;
    });
    // Remove from inline if it was inline
    setInlineMsgIds(prev => {
      const next = new Set(prev);
      next.delete(msgId);
      return next;
    });
    // Find index in the visible list (after un-dismissing, need to search full artifacts)
    const idx = artifacts.findIndex(a => a.msgId === msgId);
    if (idx >= 0) {
      // Compute what the visible index will be after un-dismissing
      const visibleIdx = artifacts
        .filter(a => !dismissedMsgIds.has(a.msgId) || a.msgId === msgId)
        .findIndex(a => a.msgId === msgId);
      setActiveArtifactIdx(visibleIdx >= 0 ? visibleIdx : 0);
    }
  };

  // Move artifact back to side panel
  const handleMoveToSide = (msgId) => {
    // Un-dismiss if it was dismissed
    setDismissedMsgIds(prev => {
      const next = new Set(prev);
      next.delete(msgId);
      return next;
    });
    setInlineMsgIds(prev => {
      const next = new Set(prev);
      next.delete(msgId);
      return next;
    });
    // Find this artifact's index in visible list
    const visibleIdx = artifacts
      .filter(a => !dismissedMsgIds.has(a.msgId) || a.msgId === msgId)
      .findIndex(a => a.msgId === msgId);
    if (visibleIdx >= 0) setActiveArtifactIdx(visibleIdx);
  };

  return (
    <div className={`chat-layout ${showSidePanel ? 'chat-layout--split' : ''} ${showTerminal ? 'chat-layout--terminal' : ''}`}>
    <div className="chat-window">
      <div className="chat-header">
        {buddyObserving && (
          <div className="buddy-observing-badge">
            {buddyObserving.buddyName} is helping you
          </div>
        )}
        <ConnectComputer isConnected={agentConnected} onPair={pairAgent} />
        <button
          className={`chat-header__screen-share-btn ${screenSharing ? 'chat-header__screen-share-btn--active' : ''}`}
          onClick={() => setScreenSharing(prev => !prev)}
          title={screenSharing ? 'Stop sharing your screen' : 'Share your screen so PC Pal can see and help'}
        >
          {screenSharing ? 'Stop Sharing' : 'Share Screen'}
        </button>
        {!isViewingPast && (
          <button
            type="button"
            className={`chat-header__terminal-btn ${terminalOpen && agentConnected ? 'chat-header__terminal-btn--active' : ''}`}
            onClick={() => setTerminalOpen(prev => !prev)}
            aria-label={
              !agentConnected
                ? 'Connect your computer to use the terminal'
                : terminalOpen ? 'Close terminal' : 'Open terminal'
            }
            title={!agentConnected ? 'Connect your computer to use the terminal' : undefined}
            disabled={!agentConnected}
          >
            Terminal
          </button>
        )}
        <button
          type="button"
          className="chat-header__end-btn"
          onClick={endChat}
          disabled={!hasUserMessage || !!feedbackPrompt}
          aria-label="End chat and leave feedback"
        >
          End chat
        </button>
      </div>

      {!isConnected && (
        <div className="connection-banner" role="status">
          Connecting to PC Pal... please wait.
        </div>
      )}

      <div className="chat-messages" role="log" aria-live="polite" aria-label="Chat messages">
        {!isViewingPast && (
          <WelcomeBackBanner
            welcomeData={welcomeBack}
            onSendMessage={sendMessage}
            onDismiss={dismissWelcomeBack}
          />
        )}

        {loadingPast && (
          <div className="chat-empty">
            <p className="chat-empty__text">Loading conversation...</p>
          </div>
        )}

        {!loadingPast && messages.length === 0 && !welcomeBack && (
          <div className="chat-empty">
            <p className="chat-empty__text">
              {isViewingPast
                ? 'This conversation has no messages.'
                : <>Hello! I&apos;m PC Pal, your friendly tech helper.<br />Ask me anything about your computer!</>
              }
            </p>
          </div>
        )}

        {messages.map((msg) => (
          <MessageBubble
            key={msg.id}
            message={msg}
            onRunCommand={runCommand}
            inlineMode={inlineMsgIds.has(msg.id)}
            onMoveToSide={() => handleMoveToSide(msg.id)}
            onClickArtifact={() => navigateToArtifact(msg.id)}
          />
        ))}

        {!isViewingPast && isTyping && (
          <div className="typing-indicator" aria-live="polite" role="status">
            <div className="typing-indicator__dots">
              <span></span><span></span><span></span>
            </div>
            <span className="typing-indicator__label">PC Pal is typing...</span>
          </div>
        )}

        <div ref={bottomRef} aria-hidden="true" />
      </div>

      {isViewingPast ? (
        <div className="chat-readonly-banner">
          This is a past conversation.
        </div>
      ) : (
        <>
          <StepSequencePanel activeSequence={activeSequence} onSendMessage={sendMessage} hasBuddy={hasBuddy} />
          {screenSharing && (
            <ScreenShare
              onScreenFrame={sendScreenFrame}
              onStop={() => setScreenSharing(false)}
            />
          )}
          <MessageInput onSend={sendMessage} onGatherResources={gatherResources} isTyping={isTyping} />
        </>
      )}

      {!isViewingPast && feedbackPrompt && (
        <FeedbackModal onSubmit={submitFeedback} onSkip={skipFeedback} />
      )}
    </div>

    {showSidePanel && (
      showBuddyTerminal ? (
        <div className="side-panel side-panel--terminal">
          <div className="side-panel__header">
            <span className="side-panel__title">Terminal &mdash; {buddySession.learnerName}'s Computer</span>
            <button className="side-panel__close" onClick={() => leaveBuddySession(buddySession.learnerId)}>Leave</button>
          </div>
          <div className="buddy-session-chat">
            <div className="buddy-session-chat__label">Live Chat</div>
            <div className="buddy-session-chat__messages">
              {buddySession.messages.map((m) => (
                <div key={m.id} className={`buddy-session-chat__msg buddy-session-chat__msg--${m.role}`}>
                  <span className="buddy-session-chat__role">{m.role === 'user' ? buddySession.learnerName : 'PC Pal'}</span>
                  <span className="buddy-session-chat__text">{m.text}</span>
                </div>
              ))}
              {buddySession.messages.length === 0 && (
                <div className="buddy-session-chat__empty">No messages yet.</div>
              )}
            </div>
          </div>
          <BuddyTerminal
            terminalHistory={buddySession.terminalHistory}
            onRunCommand={(cmd) => sendBuddyCommand(buddySession.learnerId, cmd)}
            learnerName={buddySession.learnerName}
            cwd={buddySession.cwd}
          />
        </div>
      ) : showLocalTerminal ? (
        <div className="side-panel side-panel--terminal">
          <div className="side-panel__header">
            <span className="side-panel__title">Terminal</span>
            <button className="side-panel__close" onClick={() => setTerminalOpen(false)}>Close</button>
          </div>
          <BuddyTerminal
            terminalHistory={terminalHistory}
            onRunCommand={sendTerminalCommand}
            learnerName="This Computer"
            cwd={terminalCwd}
          />
        </div>
      ) : (
        <SidePanel
          artifact={currentArtifact}
          artifacts={visibleArtifacts}
          activeIndex={activeArtifactIdx}
          onNavigate={setActiveArtifactIdx}
          onClose={() => handleDismiss(currentArtifact.msgId)}
          onMoveToInline={() => handleMoveToInline(currentArtifact.msgId)}
          onRunCommand={runCommand}
          onSendMessage={sendMessage}
        />
      )
    )}
    </div>
  );
}

export default ChatWindow;

import { useState, useEffect, useLayoutEffect, useRef, useCallback } from 'react';
import { collectBrowserSystemInfo } from '../utils/collectBrowserSystemInfo';

/**
 * useChat — WebSocket chat hook for PC Pal
 *
 * Connects to /ws (proxied to ws://localhost:3001/ws by Vite),
 * sends an init message, and manages message state.
 *
 * @param {string|null} userId
 * @returns {object} chat state + callbacks (see destructured return below)
 */
export function useChat(userId) {
  const [messages, setMessages] = useState([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const [connectionFailed, setConnectionFailed] = useState(false);
  const [activeSequence, setActiveSequence] = useState(null);
  const [welcomeBack, setWelcomeBack] = useState(null);
  const [conversationId, setConversationId] = useState(null);
  const [feedbackPrompt, setFeedbackPrompt] = useState(null);
  const [agentConnected, setAgentConnected] = useState(false);
  // Standalone terminal history (user's own terminal panel)
  const [terminalHistory, setTerminalHistory] = useState([]);
  const [terminalCwd, setTerminalCwd] = useState(null);
  // Buddy session state — set when THIS user is observing a learner's session
  const [buddySession, setBuddySession] = useState(null);
  // Set when a buddy is observing OUR session (we are the learner)
  const [buddyObserving, setBuddyObserving] = useState(null);

  const wsRef = useRef(null);
  const reconnectTimeoutRef = useRef(null);
  const messageIdRef = useRef(0);
  const reconnectAttemptsRef = useRef(0);
  const connectRef = useRef(null);
  const conversationIdRef = useRef(null);

  const nextId = () => {
    messageIdRef.current += 1;
    return messageIdRef.current;
  };

  // Keep a ref in sync so callbacks can read the latest conversation id
  // without being re-created on every change.
  useEffect(() => {
    conversationIdRef.current = conversationId;
  }, [conversationId]);

  const connect = useCallback(() => {
    if (!userId) return;

    // Determine WS URL: use relative path so Vite proxy handles it
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${window.location.host}/ws`;

    const ws = new WebSocket(wsUrl);
    wsRef.current = ws;

    ws.onopen = () => {
      setIsConnected(true);
      setConnectionFailed(false);
      reconnectAttemptsRef.current = 0;
      // Send init message so the server knows who we are
      const browserSystemInfo = collectBrowserSystemInfo();
      ws.send(JSON.stringify({ type: 'init', userId, browserSystemInfo }));
    };

    ws.onmessage = (event) => {
      let data;
      try {
        data = JSON.parse(event.data);
      } catch {
        console.error('PC Pal: invalid JSON from server', event.data);
        return;
      }

      switch (data.type) {
        case 'init_ack':
          if (data.conversationId) {
            setConversationId(data.conversationId);
          }
          break;

        case 'welcome_back':
          setWelcomeBack({
            reviewSkills: data.reviewSkills || [],
            pendingHelp: data.pendingHelp || [],
          });
          break;

        case 'typing':
          setIsTyping(true);
          break;

        case 'response':
          setIsTyping(false);
          setMessages((prev) => [
            ...prev,
            {
              id: nextId(),
              role: 'assistant',
              text: data.text ?? '',
              timestamp: new Date().toISOString(),
              safetyAlert: data.safetyAlert ?? null,
              stepSequence: data.stepSequence || null,
              images: data.images || null,
              videos: data.videos || null,
              guide: data.guide || null,
              findings: data.findings || null,
              practice: data.practice || null,
              screenshot: data.screenshot || null,
            },
          ]);
          if (data.stepSequence) {
            if (data.stepSequence.completed) {
              setActiveSequence(null);
            } else {
              setActiveSequence(data.stepSequence);
            }
          }
          if (data.conversationId) {
            setConversationId(data.conversationId);
          }
          if (data.endedConversationId) {
            setFeedbackPrompt({ conversationId: data.endedConversationId });
          }
          break;

        case 'resources':
          setIsTyping(false);
          setMessages((prev) => [
            ...prev,
            {
              id: nextId(),
              role: 'assistant',
              text: data.text ?? '',
              timestamp: new Date().toISOString(),
              resources: data.resources || null,
            },
          ]);
          break;

        case 'command_result':
          // Update the command result in the most recent message's guide
          setMessages((prev) => {
            const updated = [...prev];
            // Find the latest assistant message with a guide
            for (let i = updated.length - 1; i >= 0; i--) {
              if (updated[i].guide) {
                updated[i] = {
                  ...updated[i],
                  commandResults: {
                    ...(updated[i].commandResults || {}),
                    [data.command]: { output: data.output, running: false, error: data.error },
                  },
                };
                break;
              }
            }
            return updated;
          });
          break;

        case 'pair_result':
          if (data.success) {
            setAgentConnected(true);
          }
          // The callback is handled via pairAgent below
          break;

        case 'agent_status':
          setAgentConnected(!!data.connected);
          break;

        case 'new_chat_ack':
          // Server created a fresh session after closing the previous one
          setMessages([]);
          setActiveSequence(null);
          setFeedbackPrompt(null);
          if (data.conversationId) {
            setConversationId(data.conversationId);
          }
          break;

        case 'chat_ended':
          // User clicked "End chat". Server confirmed the session is closed;
          // show the feedback modal.
          if (data.conversationId) {
            setFeedbackPrompt({ conversationId: data.conversationId });
          }
          break;

        case 'error':
          setIsTyping(false);
          setMessages((prev) => [
            ...prev,
            {
              id: nextId(),
              role: 'assistant',
              text: data.message ?? 'Something went wrong. Please try again.',
              timestamp: new Date().toISOString(),
              safetyAlert: null,
            },
          ]);
          break;

        case 'terminal_result':
          setTerminalHistory(prev => prev.map(entry =>
            entry.requestId === data.requestId
              ? { ...entry, output: data.output, error: data.error, running: false }
              : entry
          ));
          if (data.cwd) setTerminalCwd(data.cwd);
          break;

        // ─── Buddy session messages ───
        case 'buddy_join_ack':
          setBuddySession({
            learnerId: data.learnerId,
            learnerName: data.learnerName,
            messages: (data.messages || []).map((m, i) => ({ ...m, id: 'bh_' + i })),
            terminalHistory: [],
          });
          break;

        case 'buddy_chat_forward':
          setBuddySession(prev => prev ? {
            ...prev,
            messages: [...prev.messages, { id: 'bf_' + Date.now(), role: data.role, text: data.text, timestamp: data.timestamp }],
          } : prev);
          break;

        case 'buddy_command_result':
          setBuddySession(prev => {
            if (!prev) return prev;
            return {
              ...prev,
              cwd: data.cwd || prev.cwd,
              terminalHistory: prev.terminalHistory.map(entry =>
                entry.requestId === data.requestId
                  ? { ...entry, output: data.output, error: data.error, running: false }
                  : entry
              ),
            };
          });
          break;

        case 'buddy_joined':
          setBuddyObserving({ buddyName: data.buddyName });
          break;

        case 'buddy_left':
          setBuddyObserving(null);
          break;

        case 'buddy_terminal_start':
          // Learner sees buddy starting a command
          setMessages(prev => [...prev, {
            id: 'bt_' + data.requestId,
            role: 'assistant',
            text: `${data.buddyName} is running a diagnostic command...`,
            timestamp: new Date().toISOString(),
            buddyTerminal: { requestId: data.requestId, command: data.command, output: '', error: false, running: true, buddyName: data.buddyName },
          }]);
          break;

        case 'buddy_terminal_result':
          // Update the pending terminal message with the result
          setMessages(prev => prev.map(m =>
            m.buddyTerminal && m.buddyTerminal.requestId === data.requestId
              ? { ...m, text: `${data.buddyName} ran: ${data.command}`, buddyTerminal: { ...m.buddyTerminal, output: data.output, error: data.error, running: false } }
              : m
          ));
          break;

        default:
          console.warn('PC Pal: unknown message type', data.type);
      }
    };

    ws.onclose = () => {
      setIsConnected(false);
      setIsTyping(false);
      const attempts = reconnectAttemptsRef.current;
      if (attempts >= 5) {
        setConnectionFailed(true);
        return;
      }
      reconnectAttemptsRef.current = attempts + 1;
      const delay = Math.min(1000 * Math.pow(2, attempts), 30000);
      reconnectTimeoutRef.current = setTimeout(() => connectRef.current?.(), delay);
    };

    ws.onerror = (err) => {
      console.error('PC Pal WebSocket error', err);
      ws.close();
    };
  }, [userId]);

  // Keep the ref in sync so ws.onclose can call the latest connect without
  // capturing it as a const (which would be a temporal dead zone violation).
  useLayoutEffect(() => {
    connectRef.current = connect;
  });

  useEffect(() => {
    if (!userId) return;
    connect();

    return () => {
      clearTimeout(reconnectTimeoutRef.current);
      if (wsRef.current) {
        // Remove the onclose handler before closing so we don't trigger reconnect
        wsRef.current.onclose = null;
        wsRef.current.close();
      }
    };
  }, [userId, connect]);

  /**
   * Send a chat message.
   * @param {string} text
   */
  const sendMessage = useCallback(
    (text) => {
      const trimmed = text.trim();
      if (!trimmed) return;

      // Optimistically add the user's message to the list
      setMessages((prev) => [
        ...prev,
        {
          id: nextId(),
          role: 'user',
          text: trimmed,
          timestamp: new Date().toISOString(),
          safetyAlert: null,
        },
      ]);

      if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify({ type: 'chat', text: trimmed }));
      } else {
        console.warn('PC Pal: WebSocket not open, message not sent');
        setMessages((prev) => [
          ...prev,
          {
            id: nextId(),
            role: 'assistant',
            text: 'Sorry, the connection was lost. Please refresh the page and try again.',
            timestamp: new Date().toISOString(),
            safetyAlert: null,
          },
        ]);
      }
    },
    [],
  );

  const dismissWelcomeBack = useCallback(() => setWelcomeBack(null), []);

  /**
   * Pair with a relay agent using a code. Calls back with { success, message }.
   */
  const pairAgent = useCallback((code, callback) => {
    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
      callback({ success: false, message: 'Not connected to PC Pal server.' });
      return;
    }
    // Listen for the pair result
    const handler = (event) => {
      let data;
      try { data = JSON.parse(event.data); } catch { return; }
      if (data.type === 'pair_result') {
        wsRef.current.removeEventListener('message', handler);
        if (data.success) setAgentConnected(true);
        callback(data);
      }
    };
    wsRef.current.addEventListener('message', handler);
    wsRef.current.send(JSON.stringify({ type: 'pair_agent', code }));
  }, []);

  /**
   * Gather resources (videos + links) related to the conversation.
   * Optionally takes extra text from the input field for context.
   */
  const gatherResources = useCallback((extraText) => {
    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) return;
    setIsTyping(true);
    // Add a user message showing what was requested
    const displayText = extraText
      ? `Find resources about: ${extraText}`
      : 'Find resources related to our conversation';
    setMessages((prev) => [
      ...prev,
      { id: nextId(), role: 'user', text: displayText, timestamp: new Date().toISOString() },
    ]);
    wsRef.current.send(JSON.stringify({
      type: 'gather_resources',
      text: extraText || '',
    }));
  }, []);

  /**
   * Run a user-approved command from a guide artifact.
   * Sets the command as "running" immediately, then sends to server.
   */
  const runCommand = useCallback((command) => {
    if (!command) return;
    // Mark as running in the most recent guide
    setMessages((prev) => {
      const updated = [...prev];
      for (let i = updated.length - 1; i >= 0; i--) {
        if (updated[i].guide) {
          updated[i] = {
            ...updated[i],
            commandResults: {
              ...(updated[i].commandResults || {}),
              [command]: { output: '', running: true, error: false },
            },
          };
          break;
        }
      }
      return updated;
    });
    // Send to server
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: 'run_command', command }));
    }
  }, []);

  /**
   * Start a fresh conversation. Closes the current session server-side
   * and creates a new one. The server replies with `new_chat_ack`.
   */
  const startNewChat = useCallback(() => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: 'new_chat' }));
    }
  }, []);

  /**
   * Trigger the end-of-chat flow. Tells the server to close the session;
   * the server replies with `chat_ended` and the hook opens the modal.
   */
  const endChat = useCallback(() => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: 'end_chat' }));
    } else if (conversationIdRef.current) {
      // WS not open — fall back to opening the modal locally so the user
      // can still leave feedback. The POST below will still persist it.
      setFeedbackPrompt({ conversationId: conversationIdRef.current });
    }
  }, []);

  /**
   * Reset local state after the server has closed a conversation.
   */
  const resetChatLocally = useCallback(() => {
    setMessages([]);
    setActiveSequence(null);
    setConversationId(null);
    setFeedbackPrompt(null);
  }, []);

  /**
   * POST the rating + optional comment to /api/quality/feedback.
   * On success, resets local state so the next message starts a fresh chat.
   * @param {{ rating: number, comment?: string }} payload
   */
  const submitFeedback = useCallback(async ({ rating, comment }) => {
    const target = feedbackPrompt?.conversationId;
    if (!target || !userId) {
      resetChatLocally();
      return { ok: false, error: 'missing_context' };
    }
    try {
      const res = await fetch('/api/quality/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          conversationId: target,
          userId,
          rating,
          comment: comment || null,
        }),
      });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        console.error('PC Pal: feedback POST failed', res.status, body);
        return { ok: false, error: body.error || `http_${res.status}` };
      }
    } catch (err) {
      console.error('PC Pal: feedback POST threw', err);
      return { ok: false, error: 'network' };
    }
    resetChatLocally();
    return { ok: true };
  }, [feedbackPrompt, userId, resetChatLocally]);

  /**
   * User dismissed the feedback modal — POST to /skip so the session closes
   * cleanly without recording a rating.
   */
  const skipFeedback = useCallback(async () => {
    const target = feedbackPrompt?.conversationId;
    if (target && userId) {
      try {
        await fetch('/api/quality/feedback/skip', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ conversationId: target, userId }),
        });
      } catch (err) {
        console.error('PC Pal: feedback skip POST threw', err);
      }
    }
    resetChatLocally();
  }, [feedbackPrompt, userId, resetChatLocally]);

  const terminalCmdIdRef = useRef(0);
  const sendTerminalCommand = useCallback((command) => {
    const trimmed = command.trim();
    if (!trimmed) return;
    terminalCmdIdRef.current += 1;
    const requestId = 'tcmd_' + terminalCmdIdRef.current + '_' + Date.now();
    setTerminalHistory(prev => [...prev, { requestId, command: trimmed, output: '', error: false, running: true }]);
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
