import React, { useState, useRef, useEffect } from 'react';
import './Terminal.css';

function shortenPath(p) {
  if (!p) return '';
  const home = p.match(/^(\/Users\/[^/]+|\/home\/[^/]+|C:\\Users\\[^\\]+)/);
  if (home) return '~' + p.slice(home[0].length);
  return p;
}

function Terminal({ terminalHistory, onRunCommand, disabled, cwd }) {
  const [input, setInput] = useState('');
  const outputRef = useRef(null);

  useEffect(() => {
    if (outputRef.current) {
      outputRef.current.scrollTop = outputRef.current.scrollHeight;
    }
  }, [terminalHistory]);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!input.trim() || disabled) return;
    onRunCommand(input.trim());
    setInput('');
  };

  return (
    <div className="terminal">
      <div className="terminal__output" ref={outputRef}>
        {terminalHistory.length === 0 && (
          <div className="terminal__empty">
            Type a diagnostic command below to run it on this computer.
            <br />
            Only safe, read-only commands are allowed.
          </div>
        )}
        {terminalHistory.map((entry) => (
          <div key={entry.requestId} className="terminal__entry">
            <div className="terminal__prompt">
              <span className="terminal__dollar">$</span>
              <span className="terminal__cmd">{entry.command}</span>
            </div>
            {entry.running ? (
              <div className="terminal__running">Running...</div>
            ) : (
              <pre className={`terminal__result ${entry.error ? 'terminal__result--err' : ''}`}>
                {entry.output || '(no output)'}
              </pre>
            )}
          </div>
        ))}
      </div>
      <form className="terminal__input-bar" onSubmit={handleSubmit}>
        {cwd && <span className="terminal__cwd">{shortenPath(cwd)}</span>}
        <span className="terminal__input-dollar">$</span>
        <input
          type="text"
          className="terminal__input"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="e.g. df -h"
          disabled={disabled}
          autoFocus
        />
        <button
          type="submit"
          className="terminal__run-btn"
          disabled={disabled || !input.trim()}
        >
          Run
        </button>
      </form>
    </div>
  );
}

export default Terminal;

