.terminal {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: #0f172a;
  border-radius: 0 0 8px 8px;
  overflow: hidden;
}

.terminal__output {
  flex: 1;
  overflow-y: auto;
  padding: 12px 14px;
  font-family: 'SF Mono', 'Fira Code', 'Consolas', monospace;
  font-size: 13px;
  line-height: 1.5;
}

.terminal__empty {
  color: #64748b;
  font-size: 13px;
  line-height: 1.6;
  padding: 16px 0;
}

.terminal__entry {
  margin-bottom: 12px;
}

.terminal__entry:last-child {
  margin-bottom: 4px;
}

.terminal__prompt {
  display: flex;
  gap: 6px;
  align-items: baseline;
}

.terminal__dollar {
  color: #4ade80;
  font-weight: 700;
  flex-shrink: 0;
}

.terminal__cmd {
  color: #a5f3fc;
  word-break: break-all;
}

.terminal__running {
  color: #facc15;
  font-style: italic;
  padding: 2px 0 0 16px;
  animation: terminal-pulse 1.2s ease-in-out infinite;
}

@keyframes terminal-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.terminal__result {
  color: #d1d5db;
  margin: 2px 0 0;
  padding: 2px 0 0 16px;
  white-space: pre-wrap;
  word-break: break-all;
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  max-height: 200px;
  overflow-y: auto;
}

.terminal__result--err {
  color: #fca5a5;
}

.terminal__input-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  background: #1e293b;
  border-top: 1px solid #334155;
  flex-shrink: 0;
}

.terminal__cwd {
  color: #60a5fa;
  font-family: 'SF Mono', 'Fira Code', 'Consolas', monospace;
  font-size: 13px;
  flex-shrink: 0;
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  direction: rtl;
  text-align: left;
}

.terminal__input-dollar {
  color: #4ade80;
  font-family: 'SF Mono', 'Fira Code', 'Consolas', monospace;
  font-weight: 700;
  font-size: 14px;
  flex-shrink: 0;
}

.terminal__input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: #e2e8f0;
  font-family: 'SF Mono', 'Fira Code', 'Consolas', monospace;
  font-size: 14px;
  padding: 4px 0;
}

.terminal__input::placeholder {
  color: #475569;
}

.terminal__run-btn {
  background: #16a34a;
  color: white;
  border: none;
  border-radius: 6px;
  padding: 5px 14px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  flex-shrink: 0;
}

.terminal__run-btn:hover:not(:disabled) {
  background: #15803d;
}

.terminal__run-btn:disabled {
  background: #475569;
  cursor: not-allowed;
}

