        if (updated[i].guide) {
          updated[i] = {
            ...updated[i],
            commandResults: {
              ...(updated[i].commandResults || {}),
              [command]: { output: '', running: true, error: false },
            },
          };
          break;
        }
      }
      return updated;
    });
    // Send to server
