      wsRef.current.send(JSON.stringify({ type: 'buddy_command', learnerId, command: trimmed, requestId }));
    }
  }, []);

  return {
    messages,
    sendMessage,
    gatherResources,
    pairAgent,
    agentConnected,
    runCommand,
    isConnected,
    isTyping,
    connectionFailed,
    activeSequence,
    welcomeBack,
    dismissWelcomeBack,
    conversationId,
    feedbackPrompt,
    startNewChat,
    endChat,
    submitFeedback,
    skipFeedback,
    terminalHistory,
    terminalCwd,
    sendTerminalCommand,
    buddySession,
    buddyObserving,
    joinBuddySession,
    leaveBuddySession,
    sendBuddyCommand,
    sendScreenFrame: useCallback((imageBase64) => {
      if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify({ type: 'screen_frame', imageBase64 }));
      }
    }, []),
    wsRef,
  };
}
