  }, [userId]);

  // Keep the ref in sync so ws.onclose can call the latest connect without
  // capturing it as a const (which would be a temporal dead zone violation).
  useLayoutEffect(() => {
    connectRef.current = connect;
  });

  useEffect(() => {
