  const sendTerminalCommand = useCallback((command) => {
    const trimmed = command.trim();
    if (!trimmed) return;
    terminalCmdIdRef.current += 1;
    const requestId = 'tcmd_' + terminalCmdIdRef.current + '_' + Date.now();
