              if (updated[i].guide) {
                updated[i] = {
                  ...updated[i],
                  commandResults: {
                    ...(updated[i].commandResults || {}),
                    [data.command]: { output: data.output, running: false, error: data.error },
                  },
                };
                break;
              }
            }
            return updated;
          });
          break;

        case 'pair_result':
          if (data.success) {
            setAgentConnected(true);
          }
          // The callback is handled via pairAgent below
          break;

        case 'agent_status':
