   */
  const pairAgent = useCallback((code, callback) => {
    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
      callback({ success: false, message: 'Not connected to PC Pal server.' });
      return;
    }
    // Listen for the pair result
