    if (msg.role !== 'assistant') continue;
    const hasAny = msg.guide || msg.resources || msg.findings || msg.videos || msg.practice;
    if (!hasAny) continue;

    artifacts.push({
      msgId: msg.id,
      guide: msg.guide || null,
      findings: msg.findings || null,
      resources: msg.resources || null,
      videos: msg.videos || null,
      practice: msg.practice || null,
    });
  }
  return artifacts;
}

function ChatWindow({ userId, hasBuddy, viewingConversationId, onConversationChange, startNewChatRef, buddySessionTarget, onBuddySessionChange }) {
  const {
    messages: liveMessages,
    sendMessage,
    gatherResources,
    pairAgent,
    agentConnected,
    runCommand,
    isConnected,
    isTyping,
    activeSequence,
    welcomeBack,
    dismissWelcomeBack,
    conversationId,
    feedbackPrompt,
    startNewChat,
    endChat,
    submitFeedback,
    skipFeedback,
    terminalHistory,
    terminalCwd,
    sendTerminalCommand,
    buddySession,
    buddyObserving,
    joinBuddySession,
    leaveBuddySession,
    sendBuddyCommand,
    sendScreenFrame,
