  const handleMoveToInline = (msgId) => {
    setInlineMsgIds(prev => new Set([...prev, msgId]));
    // If this was the active artifact, close the panel
    if (currentArtifact && currentArtifact.msgId === msgId) {
      setActiveArtifactIdx(-1);
    }
  };

