        <div className="side-panel side-panel--terminal">
          <div className="side-panel__header">
            <span className="side-panel__title">Terminal</span>
            <button className="side-panel__close" onClick={() => setTerminalOpen(false)}>Close</button>
          </div>
          <BuddyTerminal
