function ChatWindow({ userId, viewingConversationId, onConversationChange, startNewChatRef }) {
  const {
    messages: liveMessages,
    sendMessage,
    gatherResources,
    pairAgent,
    agentConnected,
    runCommand,
    isConnected,
    isTyping,
    activeSequence,
    welcomeBack,
    dismissWelcomeBack,
    conversationId,
    feedbackPrompt,
    startNewChat,
    endChat,
    submitFeedback,
    skipFeedback,
    terminalHistory,
    terminalCwd,
    sendTerminalCommand,
    sendScreenFrame,
  } = useChat(userId);
  const [screenSharing, setScreenSharing] = useState(false);
  const bottomRef = useRef(null);

  // Expose startNewChat to parent via ref
  useEffect(() => {
    if (startNewChatRef) startNewChatRef.current = startNewChat;
  }, [startNewChat, startNewChatRef]);

  // React to buddy session target from App
