        <>
          <StepSequencePanel activeSequence={activeSequence} onSendMessage={sendMessage} hasBuddy={hasBuddy} />
          {screenSharing && (
            <ScreenShare
              onScreenFrame={sendScreenFrame}
              onStop={() => setScreenSharing(false)}
            />
