  const totalSteps = steps?.length ?? 0;
  const safeIndex = Math.max(0, Math.min(currentIndex ?? 0, totalSteps - 1));
  const currentStep = steps?.[safeIndex] ?? '';
  const isLastStep = safeIndex >= totalSteps - 1;
