/* Terminal side panel override — dark background */","originalFile":"/* ChatWindow styles */

/* Split-pane layout container */
.chat-layout {
  display: flex;
  flex: 1;
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.chat-layout .chat-window {
  flex: 1;
  min-width: 0;
  height: 100%;
  overflow: hidden;
}

.chat-window {
  display: flex;
  flex-direction: column;
  flex: 1;
  height: 100%;
  min-height: 0;
  background-color: var(--color-bg);
  position: relative;
}

/* Chat header — holds the End chat button */
.chat-header {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  padding: 10px 20px;
  border-bottom: 1px solid var(--color-border);
  background-color: var(--color-white);
  flex-shrink: 0;
}

.chat-header__screen-share-btn {
  font: inherit;
  font-size: 15px;
  font-weight: 600;
  padding: 8px 16px;
  border-radius: 8px;
  border: 2px solid #16a34a;
  background: #f0fdf4;
  color: #16a34a;
  cursor: pointer;
  white-space: nowrap;
}

.chat-header__screen-share-btn:hover {
  background: #16a34a;
  color: white;
}

.chat-header__screen-share-btn--active {
  background: #16a34a;
  color: white;
  border-color: #16a34a;
  animation: screen-share-pulse 2s ease-in-out infinite;
}

.chat-header__screen-share-btn--active:hover {
  background: #dc2626;
  border-color: #dc2626;
}

@keyframes screen-share-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.8; }
}

.chat-header__end-btn {
  font: inherit;
  font-weight: 600;
  background-color: var(--color-white);
  color: var(--color-text);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 8px 16px;
  cursor: pointer;
  transition: border-color 120ms ease, background-color 120ms ease, color 120ms ease;
}

.chat-header__end-btn:hover:not(:disabled),
.chat-header__end-btn:focus-visible {
  border-color: var(--color-primary);
  color: var(--color-primary);
  outline: none;
}

.chat-header__end-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.chat-header__terminal-btn {
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  background-color: #1e293b;
  color: #e2e8f0;
  border: 2px solid #334155;
  border-radius: var(--radius-md);
  padding: 6px 14px;
  cursor: pointer;
  transition: background-color 120ms ease, border-color 120ms ease;
}

.chat-header__terminal-btn:hover {
  background-color: #0f172a;
  border-color: #4ade80;
}

.chat-header__terminal-btn--active {
  background-color: #0f172a;
  border-color: #4ade80;
  color: #4ade80;
}

.chat-header__terminal-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  border-color: #334155;
  background-color: #1e293b;
  color: #94a3b8;
}

.chat-header__terminal-btn:disabled:hover {
  background-color: #1e293b;
  border-color: #334155;
}

@media (min-width: 768px) {
  .chat-header {
    padding: 12px 40px;
  }
}

/* Connection status banner */
.connection-banner {
  background-color: var(--color-warning-light);
  color: var(--color-warning);
  border-bottom: 2px solid var(--color-warning);
  font-size: 18px;
  font-weight: 600;
  text-align: center;
  padding: 12px 20px;
  flex-shrink: 0;
}

/* Scrollable message list */
.chat-messages {
  flex: 1;
  overflow-y: auto;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  scroll-behavior: smooth;
}

/* Responsive max width for readability */
@media (min-width: 768px) {
  .chat-messages {
    padding: 28px 40px;
  }
}

/* Empty state */
.chat-empty {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 40px;
}

.chat-empty__text {
  font-size: 22px;
  color: var(--color-text-light);
  line-height: 1.7;
  max-width: 480px;
  border: 2px dashed var(--color-border);
  border-radius: var(--radius-lg);
  padding: 32px 40px;
  background-color: var(--color-white);
}

/* Typing indicator */
.typing-indicator {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0 4px;
  margin-bottom: 4px;
}

.typing-indicator__dots {
  display: flex;
  align-items: center;
  gap: 5px;
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: 10px 16px;
  box-shadow: 0 1px 4px var(--color-shadow);
}

.typing-indicator__dots span {
  display: block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--color-primary);
  animation: pulse 1.4s ease-in-out infinite;
}

.typing-indicator__dots span:nth-child(2) {
  animation-delay: 0.2s;
}

.typing-indicator__dots span:nth-child(3) {
  animation-delay: 0.4s;
}

.typing-indicator__label {
  font-size: 17px;
  color: var(--color-text-light);
  font-style: italic;
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.3; transform: scale(0.8); }
}

/* ─── Buddy terminal expanded panel ─── */
.chat-layout--terminal .side-panel {
  width: 50%;
  max-width: 60vw;
}

