  padding: 8px 14px 4px;
  background: #1e293b;
  flex-shrink: 0;
}

.buddy-session-chat__messages {
  flex: 1;
  overflow-y: auto;
  padding: 6px 14px 10px;
  background: #1e293b;
}

.buddy-session-chat__msg {
  margin-bottom: 6px;
  font-size: 13px;
  line-height: 1.4;
}

.buddy-session-chat__role {
  font-weight: 700;
  margin-right: 6px;
}

.buddy-session-chat__msg--user .buddy-session-chat__role {
  color: #60a5fa;
}

.buddy-session-chat__msg--assistant .buddy-session-chat__role {
  color: #a78bfa;
}

.buddy-session-chat__text {
  color: #d1d5db;
}

.buddy-session-chat__empty {
  color: #64748b;
  font-size: 13px;
  font-style: italic;
  padding: 8px 0;
}

/* Terminal side panel override — dark background */
.side-panel--terminal {
  background: #0f172a;
}

.side-panel--terminal .side-panel__header {
  background: linear-gradient(135deg, #1e293b, #0f172a);
  border-bottom: 1px solid #334155;
}

.side-panel--terminal .side-panel__title {
  color: #e2e8f0;
}

.side-panel--terminal .side-panel__close {
  background: #334155;
  color: #e2e8f0;
}

.side-panel--terminal .side-panel__close:hover {
  background: #475569;
}
