/* MessageBubble styles */

.message-row {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  margin-bottom: 20px;
  animation: fadeIn 300ms ease forwards;
  max-width: 100%;
}

.message-row--user {
  flex-direction: row-reverse;
}

.message-row--assistant {
  flex-direction: row;
}

/* Small avatar label for the assistant */
.message-avatar {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: var(--color-primary);
  color: var(--color-white);
  font-size: 16px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}

/* The bubble itself */
.bubble {
  max-width: min(80%, 620px);
  padding: 18px 22px;
  border-radius: 18px;
  word-break: break-word;
}

.bubble--user {
  background-color: var(--color-primary);
  color: var(--color-white);
  border-bottom-right-radius: 4px;
}

.bubble--assistant {
  background-color: var(--color-white);
  color: var(--color-text);
  border: 1px solid var(--color-border);
  border-bottom-left-radius: 4px;
  box-shadow: 0 1px 4px var(--color-shadow);
}

/* User message — plain text */
.bubble__text {
  font-size: 20px;
  line-height: 1.6;
  margin: 0 0 8px;
  white-space: pre-wrap;
}

/* Assistant message — formatted output */
.bubble__formatted {
  font-size: 20px;
  line-height: 1.6;
}

.bubble__paragraph {
  margin: 0 0 14px;
  font-size: 20px;
  line-height: 1.6;
}

.bubble__paragraph:last-child {
  margin-bottom: 8px;
}

/* Bold text — key actions stand out */
.bubble__bold {
  font-weight: 700;
  color: var(--color-primary);
}

/* Numbered steps — big visual circles */
.bubble__step {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 16px;
  padding: 14px 16px;
  background-color: #f0f4ff;
  border-radius: 14px;
  border-left: 4px solid var(--color-primary);
}

.bubble__step:last-of-type {
  margin-bottom: 14px;
}

.bubble__step-num {
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background-color: var(--color-primary);
  color: var(--color-white);
  font-size: 20px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
}

.bubble__step-text {
  font-size: 20px;
  line-height: 1.5;
  padding-top: 6px;
}

.bubble__step-text .bubble__bold {
  font-weight: 700;
  color: #1a3a8a;
}

/* User screen screenshot (from take_screenshot) */
.bubble__screenshot-annotated {
  margin-top: 12px;
  margin-bottom: 10px;
  border-radius: 12px;
  overflow: hidden;
  border: 3px solid #FF3333;
  box-shadow: 0 4px 12px rgba(255, 51, 51, 0.15);
}

.bubble__screenshot-annotated .bubble__screenshot-img {
  width: 100%;
  display: block;
  cursor: zoom-in;
}

.bubble__screenshot-annotated .bubble__screenshot-caption {
  font-size: 14px;
  color: #475569;
  padding: 8px 12px;
  margin: 0;
  background: #fef2f2;
  border-top: 1px solid #fecaca;
}

/* Annotated device screenshots */
.bubble__screenshots {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 16px;
  margin-bottom: 12px;
}

.bubble__screenshot-card {
  flex: 1 1 200px;
  max-width: 280px;
  background: #f8f9fa;
  border: 2px solid var(--color-border, #e0e0e0);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.bubble__screenshot-img {
  width: 100%;
  display: block;
}

.bubble__screenshot-caption {
  font-size: 15px;
  color: var(--color-text-light, #666);
  text-align: center;
  padding: 8px 10px;
  margin: 0;
  border-top: 1px solid var(--color-border, #e0e0e0);
  background: #fff;
}

/* Artifact reference tag — clickable, shown in chat when artifact is in side panel */
.bubble__artifact-tag {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  padding: 8px 12px;
  background: #eef2ff;
  border: 1px solid #c7d2fe;
  border-radius: 8px;
  font-size: 14px;
  cursor: pointer;
  width: 100%;
  text-align: left;
  transition: background 120ms, border-color 120ms;
}

.bubble__artifact-tag:hover {
  background: #dbeafe;
  border-color: var(--color-primary, #2563eb);
}

.bubble__artifact-tag-icon {
  color: var(--color-primary, #2563eb);
  font-size: 16px;
}

.bubble__artifact-tag-label {
  font-weight: 600;
  color: #334155;
}

.bubble__artifact-tag-hint {
  color: #94a3b8;
  font-size: 13px;
  margin-left: auto;
}

/* Open in side panel / move to inline button */
.bubble__side-btn {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-primary, #2563eb);
  background: #eef2ff;
  border: 1px solid #c7d2fe;
  border-radius: 6px;
  padding: 5px 12px;
  cursor: pointer;
  margin-top: 8px;
}

.bubble__side-btn:hover {
  background: var(--color-primary, #2563eb);
  color: white;
}

/* Timestamp */
.bubble__time {
  font-size: 16px;
  opacity: 0.7;
  display: block;
}

.bubble--user .bubble__time {
  color: var(--color-white);
  text-align: right;
}

.bubble--assistant .bubble__time {
  color: var(--color-text-light);
}

/* Safety alert banner */
.safety-alert {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  background-color: var(--color-danger-light);
  border: 2px solid var(--color-danger);
  border-radius: var(--radius-md);
  color: var(--color-danger);
  font-size: 18px;
  font-weight: 600;
  padding: 14px 18px;
  margin-bottom: 8px;
  width: 100%;
  max-width: min(80%, 620px);
  box-shadow: 0 2px 8px rgba(220, 38, 38, 0.2);
}

.safety-alert__icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background-color: var(--color-danger);
  color: var(--color-white);
  font-size: 16px;
  font-weight: 900;
  display: flex;
  align-items: center;
  justify-content: center;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ─── Buddy terminal inline ─── */
.bubble__buddy-terminal {
  margin-top: 10px;
  background: #1e293b;
  border-radius: 10px;
  overflow: hidden;
  font-family: 'SF Mono', 'Fira Code', 'Consolas', monospace;
  font-size: 13px;
}

.bubble__buddy-terminal-header {
  padding: 8px 12px;
  color: #94a3b8;
  font-size: 12px;
  font-weight: 600;
  font-family: var(--font-family);
  border-bottom: 1px solid #334155;
}

.bubble__buddy-terminal-cmd {
  padding: 8px 12px 4px;
  color: #a5f3fc;
}

.bubble__buddy-terminal-running {
  padding: 4px 12px 8px;
  color: #facc15;
  font-style: italic;
}

.bubble__buddy-terminal-output {
  padding: 4px 12px 10px;
  margin: 0;
  color: #d1d5db;
  white-space: pre-wrap;
  word-break: break-all;
  font-family: inherit;
  font-size: inherit;
  max-height: 150px;
  overflow-y: auto;
}

.bubble__buddy-terminal-output--err {
  color: #fca5a5;
}

