/* WelcomeBackBanner — shown at top of chat on return */

.welcome-banner {
  padding: 20px;
  margin: 12px;
  background: linear-gradient(135deg, #eff6ff, #dbeafe);
  border: 2px solid var(--color-primary);
  border-radius: var(--radius-lg);
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.welcome-banner__section {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.welcome-banner__section--help {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid rgba(37, 99, 235, 0.2);
}

.welcome-banner__text {
  font-size: 19px;
  font-weight: 600;
  color: var(--color-text);
  margin: 0;
  line-height: 1.5;
}

.welcome-banner__skills {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.welcome-banner__skill-btn {
  min-height: 48px;
  font-size: 17px;
}

.welcome-banner__dismiss {
  background: none;
  border: none;
  color: var(--color-text-light);
  font-size: 16px;
  cursor: pointer;
  padding: 8px 0;
  text-align: center;
  text-decoration: underline;
}

.welcome-banner__dismiss:hover {
  color: var(--color-text);
}

/* Help reply section */
.welcome-banner__help-reply {
  background: var(--color-white);
  border-radius: var(--radius-md);
  padding: 16px;
  border-left: 4px solid var(--color-success);
}

.welcome-banner__help-question {
  font-size: 15px;
  color: var(--color-text-light);
  margin: 0 0 8px;
  font-style: italic;
}

.welcome-banner__help-response {
  font-size: 18px;
  color: var(--color-text);
  margin: 0;
  line-height: 1.5;
  font-weight: 500;
}

}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ─── Buddy terminal inline ─── */
.bubble__buddy-terminal {
  margin-top: 10px;
  background: #1e293b;
  border-radius: 10px;
  overflow: hidden;
  font-family: 'SF Mono', 'Fira Code', 'Consolas', monospace;
  font-size: 13px;
}

.bubble__buddy-terminal-header {
  padding: 8px 12px;
  color: #94a3b8;
  font-size: 12px;
  font-weight: 600;
  font-family: var(--font-family);
  border-bottom: 1px solid #334155;
}

.bubble__buddy-terminal-cmd {
  padding: 8px 12px 4px;
  color: #a5f3fc;
}

.bubble__buddy-terminal-running {
  padding: 4px 12px 8px;
  color: #facc15;
  font-style: italic;
}

.bubble__buddy-terminal-output {
  padding: 4px 12px 10px;
  margin: 0;
  color: #d1d5db;
  white-space: pre-wrap;
  word-break: break-all;
  font-family: inherit;
  font-size: inherit;
  max-height: 150px;
  overflow-y: auto;
}

.bubble__buddy-terminal-output--err {
  color: #fca5a5;
}

