@media (min-width: 768px) {
  .chat-messages {
    padding: 28px 40px;
  }
}

/* Empty state */
.chat-empty {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 40px;
}

.chat-empty__text {
  font-size: 22px;
  color: var(--color-text-light);
  line-height: 1.7;
  max-width: 480px;
  border: 2px dashed var(--color-border);
  border-radius: var(--radius-lg);
  padding: 32px 40px;
  background-color: var(--color-white);
}

/* Typing indicator */
.typing-indicator {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0 4px;
  margin-bottom: 4px;
}

.typing-indicator__dots {
  display: flex;
  align-items: center;
  gap: 5px;
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  padding: 10px 16px;
  box-shadow: 0 1px 4px var(--color-shadow);
}

.typing-indicator__dots span {
  display: block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--color-primary);
  animation: pulse 1.4s ease-in-out infinite;
}

.typing-indicator__dots span:nth-child(2) {
  animation-delay: 0.2s;
}

.typing-indicator__dots span:nth-child(3) {
  animation-delay: 0.4s;
}

.typing-indicator__label {
  font-size: 17px;
  color: var(--color-text-light);
  font-style: italic;
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.3; transform: scale(0.8); }
}

/* ─── Buddy terminal expanded panel ─── */
.chat-layout--terminal .side-panel {
  width: 50%;
  max-width: 60vw;
}

.buddy-observing-badge {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-success, #16a34a);
  background: var(--color-success-light, #dcfce7);
  padding: 5px 14px;
  border-radius: var(--radius-full, 9999px);
  margin-right: auto;
}

/* ─── Buddy session chat (read-only view in side panel) ─── */
.buddy-session-chat {
  border-bottom: 1px solid #334155;
  max-height: 35%;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  overflow: hidden;
}

.buddy-session-chat__label {
  font-size: 12px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 8px 14px 4px;
  background: #1e293b;
  flex-shrink: 0;
}

.buddy-session-chat__messages {
  flex: 1;
  overflow-y: auto;
  padding: 6px 14px 10px;
  background: #1e293b;
}

.buddy-session-chat__msg {
  margin-bottom: 6px;
  font-size: 13px;
  line-height: 1.4;
}

.buddy-session-chat__role {
  font-weight: 700;
  margin-right: 6px;
}

.buddy-session-chat__msg--user .buddy-session-chat__role {
  color: #60a5fa;
}

.buddy-session-chat__msg--assistant .buddy-session-chat__role {
  color: #a78bfa;
}

.buddy-session-chat__text {
  color: #d1d5db;
}

.buddy-session-chat__empty {
  color: #64748b;
  font-size: 13px;
  font-style: italic;
  padding: 8px 0;
}

/* Terminal side panel override — dark background */
.side-panel--terminal {
  background: #0f172a;
}

.side-panel--terminal .side-panel__header {
  background: linear-gradient(135deg, #1e293b, #0f172a);
  border-bottom: 1px solid #334155;
}

.side-panel--terminal .side-panel__title {
  color: #e2e8f0;
}

.side-panel--terminal .side-panel__close {
  background: #334155;
  color: #e2e8f0;
}

.side-panel--terminal .side-panel__close:hover {
  background: #475569;
}
