/* Header styles */

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding: 16px 24px;
  background-color: var(--color-primary);
  color: var(--color-white);
  box-shadow: 0 2px 8px var(--color-shadow);
  flex-shrink: 0;
}

.app-header__brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.app-header__logo {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background-color: var(--color-white);
  color: var(--color-primary);
  font-size: 16px;
  font-weight: 900;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  letter-spacing: 0.5px;
}

.app-header__title {
  font-size: 26px;
  font-weight: 800;
  color: var(--color-white);
  margin: 0;
  line-height: 1.2;
}

.app-header__subtitle {
  font-size: 16px;
  color: rgba(255, 255, 255, 0.85);
  margin: 0;
  line-height: 1.3;
}

.app-header__user {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  background: rgba(255, 255, 255, 0.1);
  border: 2px solid rgba(255, 255, 255, 0.35);
  cursor: pointer;
  padding: 6px 14px;
  border-radius: var(--radius-md);
  transition: background var(--transition-fast), border-color var(--transition-fast);
}

.app-header__user::after {
  content: 'Edit';
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.85);
}

.app-header__user:hover {
  background: rgba(255, 255, 255, 0.25);
  border-color: rgba(255, 255, 255, 0.6);
}

.app-header__user-greeting {
  font-size: 18px;
  color: var(--color-white);
}

.app-header__user-os {
  font-size: 14px;
  color: var(--color-white);
  background-color: rgba(255, 255, 255, 0.25);
  border-radius: var(--radius-full);
  padding: 2px 10px;
}

.app-header__right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.app-header__dash-btn {
  min-width: 48px;
  min-height: 48px;
  padding: 10px 20px;
  background: rgba(255, 255, 255, 0.15);
  color: var(--color-white);
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: var(--radius-full);
  font-size: 17px;
  font-weight: 600;
  cursor: pointer;
  transition: background 120ms;
}

.app-header__dash-btn:hover {
  background: rgba(255, 255, 255, 0.35);
}

.app-header__dash-btn--active {
  background: rgba(255, 255, 255, 0.35);
  border-color: rgba(255, 255, 255, 0.7);
}

.app-header__signout {
  min-height: 44px;
  padding: 8px 16px;
  background: transparent;
  color: var(--color-white);
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: var(--radius-full);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: background 120ms;
}

.app-header__signout:hover {
  background: rgba(255, 255, 255, 0.15);
}

.app-header__buddy-btn {
  position: relative;
  min-width: 48px;
  min-height: 48px;
  padding: 10px 20px;
  background: rgba(255, 255, 255, 0.2);
  color: var(--color-white);
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-radius: var(--radius-full);
  font-size: 17px;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.app-header__buddy-btn:hover {
  background: rgba(255, 255, 255, 0.35);
}

.app-header__buddy-badge {
  position: absolute;
  top: -6px;
  right: -6px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--color-danger);
  color: var(--color-white);
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (max-width: 480px) {
  .app-header {
    padding: 12px 16px;
  }

  .app-header__title {
    font-size: 22px;
  }

  .app-header__buddy-btn {
    padding: 8px 14px;
    font-size: 15px;
  }
}

/* Profile editor modal */
.profile-edit-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.profile-edit {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: 32px;
  max-width: 420px;
  width: 90%;
  box-shadow: 0 8px 32px var(--color-shadow);
}

.profile-edit__title {
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--color-text);
  margin: 0 0 20px;
  text-align: center;
}

.profile-edit__label {
  display: block;
  font-size: var(--font-size-sm);
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 16px;
}

.profile-edit__input,
.profile-edit__select {
  display: block;
  width: 100%;
  margin-top: 6px;
  padding: 12px 14px;
  font-size: var(--font-size-base);
  color: var(--color-text);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-surface);
}

.profile-edit__input:focus,
.profile-edit__select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px var(--color-primary-light);
}

.profile-edit__checkbox {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 16px;
  font-size: var(--font-size-sm);
  color: var(--color-text);
  cursor: pointer;
}

.profile-edit__checkbox input[type="checkbox"] {
  margin-top: 4px;
  width: 18px;
  height: 18px;
  accent-color: #4ade80;
}

.profile-edit__checkbox small {
  color: #64748b;
  font-weight: 400;
}

.profile-edit__error {
  margin-top: 8px;
  padding: 10px 12px;
  background: var(--color-danger-light);
  color: var(--color-danger);
  border: 2px solid var(--color-danger);
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  font-weight: 600;
}

.profile-edit__actions {
  display: flex;
  gap: 12px;
  margin-top: 24px;
}

.profile-edit__save {
  flex: 1;
  padding: 12px;
  font-size: var(--font-size-md);
  font-weight: 700;
  border-radius: var(--radius-md);
}

.profile-edit__cancel {
  flex: 1;
  padding: 12px;
  font-size: var(--font-size-md);
  font-weight: 600;
  background: var(--color-surface);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  color: var(--color-text);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
}

.profile-edit__cancel:hover {
  background: var(--color-surface-alt);
  border-color: var(--color-text-light);
}

.profile-edit__memories-btn {
  padding: 12px;
  font-size: 16px;
  font-weight: 600;
  background: #f0f4ff;
