.memories-modal__item--pattern .memories-modal__type { color: #0ea5e9; }

.memories-modal__date {
  font-size: 12px;
  color: #94a3b8;
}

.memories-modal__content {
  font-size: 16px;
  color: #1e293b;
  line-height: 1.5;
  margin: 0;
}
