65	          credentials: 'include',
66	          body: JSON.stringify({
67	            name: name.trim(),
68	            os_type: osType,
69	            comfort_level: comfortLevel,
70	            goal_summary: goalText.trim() || null,
71	            collaboration_opt_in: wantsBuddy ? 1 : 0,
72	          }),
73	        });
74	        if (!res.ok) throw new Error('Profile update failed.');
75	        newUser = await res.json();
