77	        newUser = await createUser({
78	          name: name.trim(),
79	          os_type: osType,
80	          comfort_level: comfortLevel,
81	          goal_summary: goalText.trim() || null,
82	          collaboration_opt_in: wantsBuddy ? 1 : 0,
83	        });
84	      }
85	
86	      // If user wants a buddy, generate invite code
87	      if (wantsBuddy) {
88	        try {
89	          const res = await fetch('/api/buddy/invite', {
90	            method: 'POST',
91	            headers: { 'Content-Type': 'application/json' },
92	            body: JSON.stringify({ userId: newUser.id }),
93	          });
94	          const data = await res.json();
95	          if (data.inviteCode) {
96	            setInviteCode(data.inviteCode);
97	          }
98	        } catch (e) {
99	          console.error('Failed to generate invite code:', e);
100	        }
101	      }
102	
103	      // Save goal if provided
104	      if (goalText.trim()) {
105	        try {
106	          await fetch('/api/buddy/invite', { method: 'OPTIONS' }); // warm up
107	        } catch { /* ignore */ }
108	      }
109	
110	      await completeOnboarding(newUser.id);
111	    } catch (err) {
112	      setError('Something went wrong. Please try again.');
113	      console.error('Onboarding error:', err);
