              break;
            }
          }
          if (observers.size === 0) buddyObservers.delete(msg.learnerId);
        }
        const learnerWs = chatClients.get(msg.learnerId);
        if (learnerWs && learnerWs.readyState === 1) {
          learnerWs.send(JSON.stringify({ type: 'buddy_left' }));
        }
