            ws.send(JSON.stringify({
              type: 'buddy_command_result',
              requestId: msg.requestId,
              command: cmd,
              output: "The learner's computer is not connected. They need to pair their computer before you can run commands.",
              error: true,
              cwd: buddyCwd,
            }));
          }
          return;
        }

