        // validating against the server's filesystem would leak server
        // directory existence and give the wrong answer for the learner's
        // machine anyway.
        const buddyCdMatch = cmd.match(/^cd(?:\s+(.+))?$/);
        if (buddyCdMatch) {
          const target = (buddyCdMatch[1] || '').trim().replace(/^["']|["']$/g, '') || '~';
