        const learnerWs = chatClients.get(msg.learnerId);
        if (learnerWs && learnerWs.readyState === 1) {
          learnerWs.send(JSON.stringify({ type: 'buddy_terminal_start', requestId: msg.requestId, command: cmd, buddyName }));
