          if (ws.readyState === ws.OPEN) {
            ws.send(JSON.stringify({ type: 'new_chat_ack', conversationId: session.id }));
          }
        } catch (err) {
          console.error('[ws] Error starting new chat:', err.message);
          if (ws.readyState === ws.OPEN) {
