          // user's machine (handles ~, relative paths, symlinks, etc.)
          const cdCmd = target ? `cd "${target}" && pwd` : 'cd ~ && pwd';
          const cdResult = await sendCommandToAgent(userId, cdCmd, 10000);
          const resolvedCwd = (!cdResult || cdResult.error)
