      } else if (msg.type === 'agent_register') {
        agentCode = generatePairingCode();
        pendingAgents.set(agentCode, { ws, systemInfo: msg.systemInfo || {} });
        ws.send(JSON.stringify({ type: 'agent_registered', pairingCode: agentCode }));
