          }
          if (ws.readyState === ws.OPEN) {
            ws.send(JSON.stringify({ type: 'chat_ended', conversationId }));
          }
        } catch (err) {
          console.error('[ws] Error ending chat:', err.message);
          if (ws.readyState === ws.OPEN) {
            ws.send(JSON.stringify({ type: 'error', message: 'Unable to end the chat.' }));
          }
        }
