        if (learnerWs && learnerWs.readyState === 1) {
          learnerWs.send(JSON.stringify({ type: 'buddy_left' }));
        }
        console.log(`[buddy] User ${userId} left ${msg.learnerId}'s session`);

      } else if (msg.type === 'buddy_command') {
