        const pairs = BuddyPair.findByUserId(userId);
        const pair = pairs.find(p => p.status === 'active' &&
          (p.helper_id === userId || p.learner_id === userId) &&
          (p.helper_id === msg.learnerId || p.learner_id === msg.learnerId));
