  return createSdkMcpServer({
    name: 'pcpal-tools',
    tools: [
      // Diagnostics
      getSystemInfo,
      checkNetwork,
      listRunningApps,
      readErrorLog,
      runSafeCommand,
      checkDiskHealth,
      checkInstalledSoftware,
      getBatteryStatus,
      // Teaching
      logSkillStarted,
      suggestNextSkill,
      scheduleSkillReview,
      startStepSequence,
      advanceStep,
      completeStepSequence,
      showVisualGuide,
      // Safety
      flagEmergency,
      analyzeScamSituation,
      // User
      saveNoteForUser,
      getUserNotes,
      saveUserGoal,
      adjustVocabularyLevel,
      // Buddy
      shareProgressWithBuddy,
      askBuddyForHelp,
      // Vision
      takeScreenshot,
      // DLL Diagnosis
      diagnoseMissingDll,
      // Media
      findYoutubeVideos,
      // Memory
      saveMemory,
      recallMemories,
      // Practice
      startPractice,
      // Artifacts
      createGuide,
      createFindings,
    ],
  });
}

