      // Teaching
      logSkillStarted,
      suggestNextSkill,
      scheduleSkillReview,
      startStepSequence,
      advanceStep,
      completeStepSequence,
      showVisualGuide,
      // Safety
      flagEmergency,
      analyzeScamSituation,
      // User
      saveNoteForUser,
      getUserNotes,
      saveUserGoal,
      adjustVocabularyLevel,
      // Buddy
      shareProgressWithBuddy,
      askBuddyForHelp,
