  } else if (name === 'diagnose_missing_dll') {
    try {
      const dllName = (args.dll_name || '').toLowerCase().replace(/\.dll$/i, '') + '.dll';
      let foundFamily = null;
      let foundFamilyId = null;
      let foundVersion = null;

      // Exact match
