// Drop buddy/collaboration tables and columns left over from the removed buddy
// system. Idempotent — DROP TABLE IF EXISTS is a no-op on fresh databases, and
// the column drops are wrapped in try/catch in case the column is already gone
// or the SQLite build doesn't support DROP COLUMN.
function dropBuddyArtifacts() {
  const drops = [
